 try{if(['/api/state','/api/operations'].includes(url))url+='?project_id='+encodeURIComponent(project);if(url==='/api/command')body={project_id:project,command:body};const r=await fetch(url,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-CSRF-Token':csrf,...(auth?{Authorization:auth}:{})}:{},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok)throw Error(data.message||data.error||t("İşlem başarısız"));if(project!==activeProject)throw Error('project_changed');return data;}
