function show(id){selected=id;const task=state.tasks.find(t=>t.id===id);if(!task)return;let detail=$('detail');$('detail-shell').hidden=false;document.body.classList.add('detail-open');detail.hidden=false;detail.replaceChildren();detail.append(el('h2',task.body.title),el('p',task.body.description),el('p',t("Görev sürümü: {version} · {lane}",{version:task.version,lane:task.lane}),'muted'));
const root=detail,overview=el('section');overview.dataset.detailSection='overview';detail.append(overview);renderWorkflowControls(overview,task);renderBlockerControls(overview,task);renderRoutingControls(overview,task);
const acSection=el('section');acSection.dataset.detailSection='acceptance';root.append(acSection);detail=acSection;
const latest=task.acceptance.current?.contract;const ac=el('textarea'),dod=el('textarea'),reason=el('input');ac.id='ac';dod.id='dod';reason.id='reason';ac.value=latest?latest.criteria.map(r=>r.statement).join('\n'):`${task.body.title} çıktısı görev açıklamasındaki kapsamla karşılaştırılarak incelendi.`;dod.value=latest?latest.dod.map(r=>r.statement).join('\n'):'Yapılan değişiklik incelendi ve ilgili doğrulama sonucu kaydedildi.';reason.placeholder=t("İlk kapsam onayı veya değişiklik gerekçesi");reason.value=latest?'':'İlk kapsam ve kriter onayı';detail.append(el('p',t("İlk maddeler düzenlenebilir basit şablonlardır; otomatik AI çıkarımı değildir. Onaydan önce göreve uygunluğunu kontrol et."),'muted'));for(const [label,input] of [[t("Kabul kriterleri (her satır ayrı madde)"),ac],[t("Definition of Done (her satır ayrı madde)"),dod],[t("Onay / değişiklik gerekçesi"),reason]]){const l=el('label',label);l.htmlFor=input.id;detail.append(l,input);}const ack=el('input');ack.id='criteria_ack';ack.type='checkbox';ack.style.width='auto';const acklabel=el('label');acklabel.append(ack,document.createTextNode(t(" Önceki kriterlerdeki değişiklikleri inceledim ve açıkça onaylıyorum.")));if(latest)detail.append(acklabel);
if(latest)for(const criterion of [...latest.criteria,...latest.dod]){const label=el('label',criterion.id+' · '+t('Verification method')),method=el('select');method.id='method_'+criterion.id;for(const name of ['human_review','file_check','automatic_test']){const option=el('option',name);option.value=name;method.append(option);}method.value=criterion.method;label.htmlFor=method.id;detail.append(label,method);}
const actions=el('div',undefined,'actions');const approve=el('button',t("Kriterleri onayla")),start=el('button',t("Çalışmaya başla"),'secondary');actions.append(approve,start);detail.append(actions);approve.onclick=async()=>{try{const rows=(value,prefix)=>value.split('\n').map(v=>v.trim()).filter(Boolean).map((v,i)=>({id:prefix+(i+1),statement:v,method:$('method_'+prefix+(i+1))?.value||latest?.[prefix==='AC'?'criteria':'dod']?.find(r=>r.id===prefix+(i+1))?.method||'human_review',required:true,applicable:true,applicability_reason:''}));await request('/api/command',{action:'acceptance',task:id,task_version:task.version,base_contract:task.acceptance.current?.version||0,criteria:rows(ac.value,'AC'),dod:rows(dod.value,'DOD'),reason:reason.value,acknowledged_changes:ack.checked&&latest?[...latest.criteria,...latest.dod].map(r=>r.id):[]});message(t("Kabul kriterleri onaylandı ve yeni sürüm kalıcı kaydedildi."));await refresh();}catch(e){message(e.message,true);}};start.onclick=async()=>{try{await request('/api/command',{action:'start',task:id});message(t("Çalışma başlangıcı kaydedildi. Kriter sonuçları henüz not_run."));await refresh();}catch(e){message(e.message,true);}};
if(latest){renderEvidenceControls(detail,task);detail.append(el('h3',t("Doğrulama durumu")));const list=el('ul');for(const row of task.workflow.verification.results)list.append(el('li',`${row.id}: ${row.statement} — ${row.status}`));detail.append(list);const history=el('details'),summary=el('summary',t("Kriter geçmişi ({count} sürüm)",{count:task.acceptance.history.length}));history.append(summary);for(const item of task.acceptance.history){history.append(el('p',`v${item.version}: ${item.contract.reason}`));const rows=el('ul');for(const c of [...item.contract.criteria,...item.contract.dod])rows.append(el('li',`${c.id}: ${c.statement}`));history.append(rows);}detail.append(history);}renderTaskSources(root,task);renderTaskHistory(root,task);setDetailTab(detailTab);}
$('task-form').onsubmit=async e=>{e.preventDefault();try{await request('/api/command',{action:'create_task',title:$('title').value,description:$('description').value});$('task-form').reset();setView('board');message(t("Görev yerel veritabanına kaydedildi."));await refresh();}catch(err){message(err.message,true);}};$('stop').onclick=async()=>{try{await request('/api/shutdown',{});message(t("Uygulama kapatıldı. Bu sekmeyi kapatabilirsin."));}catch(e){message(e.message,true);}};
(async()=>{try{const token=location.hash.slice(1);history.replaceState(null,'',location.pathname);if(/^[A-Za-z0-9_-]{43}$/.test(token)){const response=await request('/api/session',{},'Bearer '+token);csrf=response.csrf;}await refresh();}catch(e){message(t("Oturum açılamadı. Decivora.command dosyasıyla yeniden başlat. ")+e.message,true);}})();

function renderQuestions(){const list=$('question-list');list.replaceChildren();const inbox=state.question_inbox;if(!inbox)return;if(!inbox.questions.length)list.append(el('p',t("Açık soru yok."),'muted'));for(const q of inbox.questions){const card=el('article',undefined,'card');card.append(el('h3',q.text),el('p',`${q.id} · v${q.revision} · ${q.status}`,'muted'));for(const option of q.options){const button=el('button',option.label,'secondary');button.disabled=q.status!=='Open';button.onclick=async()=>{button.disabled=true;try{const result=await request('/api/command',{action:'answer_question',request_id:'answer_'+crypto.randomUUID().replaceAll('-',''),question:q.id,revision:q.revision,option:option.id});message(t("Cevap kaydedildi: {status}. Uygulama onayı ayrı kalır.",{status:result.status}));await refresh();}catch(e){button.disabled=false;message(e.message,true);}};card.append(button,document.createTextNode(' '));}if(q.selection)card.append(el('p',t("Seçilen: ")+q.options.find(o=>o.id===q.selection).label));renderQuestionControls(card,q);renderDecisionReview(card,q,inbox);list.append(card);}const exceptions=inbox.answers.filter(a=>['Stale','Unmatched','Conflict'].includes(a.payload.status));if(exceptions.length){list.append(el('h3',t("İnceleme bekleyen cevaplar")));for(const row of exceptions)list.append(el('p',`${row.payload.question} · v${row.payload.revision} · ${row.payload.option} · ${row.payload.status}`));}}
$('question-form').onsubmit=async e=>{e.preventDefault();try{const options=$('question-options').value.split('\n').map(v=>v.trim()).filter(Boolean).map((label,i)=>({id:'option_'+(i+1),label}));await request('/api/command',{action:'ask_question',request_id:'question_'+crypto.randomUUID().replaceAll('-',''),text:$('question-text').value,options,task:$('question-task').value||null});$('question-form').reset();message(t("Soru kalıcı kaydedildi. Cevap gelene kadar Open kalır."));await refresh();}catch(e){message(e.message,true);}};

function renderDecisionReview(card,q,inbox){const proposals=(state.decision_proposals||[]).filter(p=>p.question===q.id&&p.revision===q.revision);const applied=proposals.find(p=>p.state==='Applied');if(applied){card.append(el('p',t("Karar kaydedildi: ")+applied.result.temp_ids.decision),el('p',t("Etkilenen görevleri değiştirmek için ayrıca etki incelemesi ve onay gerekir."),'muted'));return;}if(q.status!=='Answered')return;const proposal=proposals.at(-1);if(proposal){card.append(el('h4',t("Karar önerisi · ")+proposal.state),el('p',proposal.reason));const button=el('button',proposal.state==='Approved'?t("Onaylı kararı uygula"):t("Karar önerisini onayla"));button.disabled=proposal.state==='Stale';button.onclick=async()=>{button.disabled=true;try{await request('/api/command',proposal.state==='Approved'?{action:'apply_decision',key:proposal.id,approval:proposal.approval}:{action:'approve_decision',key:proposal.id});message(proposal.state==='Approved'?t("Karar kalıcı kaydedildi; görevler değiştirilmedi."):t("Öneri onaylandı; uygulama ayrı adımda bekliyor."));await refresh();}catch(e){button.disabled=false;message(e.message,true);}};card.append(button);if(proposal.state!=='Stale')return;card.append(el('p',t("Dayanak değişti; eski öneri uygulanamaz. Yeni öneri hazırlayabilirsin."),'muted'));}const answer=inbox.answers.find(a=>a.payload.question===q.id&&a.payload.revision===q.revision&&a.payload.status==='Selected');if(!answer)return;const label=el('label',t("Bu seçimin gerekçesi")),reason=el('textarea'),prepare=el('button',t("Karar önerisi hazırla"));reason.id='decision_reason_'+q.id;reason.maxLength=1024;label.htmlFor=reason.id;card.append(label,reason,prepare);prepare.onclick=async()=>{prepare.disabled=true;try{await request('/api/command',{action:'prepare_decision',key:'decision_'+crypto.randomUUID().replaceAll('-',''),answer_id:answer.payload.request_id,reason:reason.value});message(t("Karar önerisi hazırlandı; henüz onaylanmadı veya uygulanmadı."));await refresh();}catch(e){prepare.disabled=false;message(e.message,true);}};}

function renderQuestionControls(card,q){const details=el('details');details.append(el('summary',t("Soru yönetimi ve geçmiş")));const reason=el('textarea');reason.id='question_reason_'+q.id;reason.maxLength=1024;const label=el('label',t("Değişiklik gerekçesi"));label.htmlFor=reason.id;details.append(label,reason);for(const [text,status] of [[t("İptal et"),'Cancelled'],[q.status==='Deferred'?t("Devam ettir"):t("Ertele"),q.status==='Deferred'?'Resumed':'Deferred']]){const button=el('button',text,'secondary');button.disabled=q.status==='Cancelled';button.onclick=async()=>{button.disabled=true;try{await request('/api/command',{action:'question_state',request_id:'state_'+crypto.randomUUID().replaceAll('-',''),question:q.id,revision:q.revision,base_state:q.state_revision,status,reason:reason.value});message(t("Soru durumu kaydedildi; geçmiş kararlar silinmedi."));await refresh();}catch(e){button.disabled=false;message(e.message,true);}};details.append(button);}const text=el('textarea'),options=el('textarea');text.id='question_edit_'+q.id;options.id='question_options_'+q.id;text.value=q.text;options.value=q.options.map(o=>o.label).join('\n');for(const [name,input] of [[t("Yeni soru metni"),text],[t("Yeni seçenekler"),options]]){const label=el('label',name);label.append(input);details.append(label);}const revise=el('button',t("Yeni soru sürümünü kaydet"));revise.onclick=async()=>{try{await request('/api/command',{action:'revise_question',question:q.id,base_revision:q.revision,text:text.value,options:options.value.split('\n').map(v=>v.trim()).filter(Boolean).map((label,i)=>({id:q.options[i]?.id||'option_'+(i+1),label})),task:q.task,reason:reason.value});message(t("Yeni soru sürümü kaydedildi; eski cevaplar taşınmadı."));await refresh();}catch(e){message(e.message,true);}};details.append(revise);for(const row of q.history){const p=row.payload;details.append(el('p',row.action==='question_presented'?`v${p.revision} · ${row.snapshot_status}: ${p.text} · ${p.reason||t("İlk sunum")}`:`v${p.revision} · ${p.status}: ${p.reason}`));}for(const p of state.decision_proposals||[])if(p.question===q.id&&p.state==='Applied')details.append(el('p',`v${p.revision} ${t("karar kaydı")}: ${p.result.temp_ids.decision}`));card.append(details);}

function renderUnmatchedAnswers(){const inbox=state.question_inbox;if(!inbox)return;for(const row of inbox.answers){const a=row.payload;if(!['Unmatched','Deferred'].includes(a.status)||inbox.answers.some(r=>r.payload.original_answer===a.request_id&&r.payload.status==='Selected'))continue;const card=el('article',undefined,'card');card.append(el('p',`${a.question} · v${a.revision} · ${a.status} · ${a.option}`));const button=el('button',t("Bağlamıyla yeniden değerlendir"));button.onclick=async()=>{button.disabled=true;try{const result=await request('/api/command',{action:'associate_answer',request_id:'association_'+crypto.randomUUID().replaceAll('-',''),answer_id:a.request_id});message(t("Eşleştirme: ")+result.status+t("; karar uygulaması ayrı onay gerektirir."));await refresh();}catch(e){button.disabled=false;message(e.message,true);}};card.append(button);$('question-list').append(card);}}

function renderConversations(){const list=$('conversation-list');list.replaceChildren();$('model-status').textContent=state.model_ready?t("Model bağlantısı yapılandırılmış. Aktardığın metin analiz edilip öneriler hazırlanır; proje kaydı için inceleme gerekir."):t("Model bağlantısı henüz etkin değil. Aktarılan konuşma yerel olarak korunur; API/veri/bütçe izni olmadan modele gönderilmez. Otomatik anlam çıkarımı şu an çalıştırılamıyor.");const review=state.conversation_review;if(!review||!review.imports.length){const empty=el('div',undefined,'empty-review');empty.append(el('strong',t("Kaynaklı önerilerin burada görünecek")),el('p',t("Önce konuşma parçasını aktar. Model bağlantısı etkinleştiğinde görev, karar ve açık soru adaylarını inceleyebilirsin.")));list.append(empty);return;}for(const item of review.imports){const box=el('article',undefined,'card');box.append(el('h3',t("Konuşma · ")+({'Waiting for model':t("Model bağlantısı bekleniyor"),'Ready for review':t("İncelemeye hazır"),'Analysis failed':t("Analiz başarısız"),'Analysis unknown':t("Sonuç doğrulanamadı")}[item.status]||item.status)),el('p',t("Elle aktarılan konuşma · ")+new Date(item.source.received_at*1000).toLocaleString(DecivoraI18n.locale),'muted'));const source=el('details');source.append(el('summary',t("Orijinal konuşma")),el('p',item.source.text));box.append(source);if(item.analysis)box.append(el('p',t("Çıkarım kaynağı: ")+item.analysis.provider,'muted'));if(item.analysis){const coverage=item.analysis.coverage||'unknown';box.append(el('p',t('Extraction coverage')+': '+coverage+(coverage==='complete'?'':' · '+t('Some conversation content may be unprocessed.')),'notice'));if(item.analysis.budget_status==='overrun')box.append(el('p',t('Budget review required; further dispatch is blocked.'),'notice'));}if(item.status==='Waiting for model'&&state.model_ready){const analyze=el('button',t("Bu konuşmayı analiz et"));analyze.onclick=async()=>{analyze.disabled=true;try{await request('/api/command',{action:'analyze_conversation',source_id:item.source.id});await refresh();}catch(e){analyze.disabled=false;message(e.message,true);}};box.append(analyze);}const chosen=[];for(const c of item.candidates){const row=el('section',undefined,'card'),check=el('input');check.id='candidate_'+c.id;check.type='checkbox';check.style.width='auto';check.disabled=c.applied||c.intent==='rejected'||c.comparison.recommendation==='review_relationship';const label=el('label');label.append(check,document.createTextNode(` ${{Task:t("Görev"),Decision:t("Karar"),PendingDecision:t("Bekleyen karar")}[c.type]||c.type} · ${c.title}`));row.append(label,el('p',c.quote),el('p',`${{proposed:t("Öneri"),reported:t("Beyan"),planned:t("Plan"),rejected:t("Reddedilmiş")}[c.intent]} · ${{review_new:t("Yeni kayıt adayı"),attach_source:t("Mevcut kayıtla eşleşiyor"),review_relationship:t("İlişki incelemesi gerekli")}[c.comparison.recommendation]}${c.applied?t(" · kaydedildi"):''}`,'muted'));chosen.push([check,c.id]);box.append(row);}if(chosen.length){const accept=el('button',t("Seçili önerileri onayla ve kaydet"));accept.onclick=async()=>{accept.disabled=true;try{await request('/api/command',{action:'accept_candidates',source_id:item.source.id,key:'import_review_'+crypto.randomUUID().replaceAll('-',''),selected:chosen.filter(([check])=>check.checked).map(([,id])=>id),base_revision:review.knowledge_revision});setView('board');message(t("Seçili öneriler kaynaklarıyla kaydedildi. Task tamamlandı sayılmadı."));await refresh();}catch(e){accept.disabled=false;message(e.message,true);}};box.append(accept);}renderDialogueReview(box,item);list.append(box);}}
$('conversation-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const result=await request('/api/command',{action:'import_conversation',text:$('conversation-text').value});message(t("Konuşma alındı: ")+result.analysis.status);await refresh();}catch(error){message(error.message,true);}finally{button.disabled=false;}};

function renderMetrics(){const root=$('workspace-metrics');root.replaceChildren();const imports=state.conversation_review?.imports||[];const candidates=imports.reduce((sum,item)=>sum+item.candidates.filter(c=>!c.applied&&c.intent!=='rejected').length+(item.status_changes||[]).filter(p=>!['Applied','Rejected'].includes(p.state)).length+(item.answer_proposals||[]).filter(p=>!['Recorded','Rejected'].includes(p.state)).length+(item.relation_proposals||[]).filter(p=>!['Applied','Rejected'].includes(p.state)).length,0);const pending=(state.question_inbox?.questions||[]).filter(q=>['Open','Deferred'].includes(q.status)).length;for(const [label,value,note] of [[t("Aktarılan konuşma"),imports.length,t("Kaynak geçmişi korunur")],[t("İncelenecek öneri"),candidates,t("Onay bekleyen adaylar")],[t("Görev"),state.tasks.length,t("Bu çalışma alanında")],[t("Bekleyen soru"),pending,t("Karar bağlamı korunur")]]){const card=el('div',undefined,'metric');card.append(el('span',label),el('strong',String(value)),el('small',note));root.append(card);}}


const dialogueDrafts=new Map();
function renderDialogueReview(box,item){
 const draftKey=activeProject+':'+item.source.id;
 const drafts=dialogueDrafts.get(draftKey)||{};
 dialogueDrafts.set(draftKey,drafts);
 if(!item.analysis||item.analysis.analysis_method==='external_response_import'){
  const tools=el('details');tools.dataset.dialogueSource=item.source.id;
  tools.append(el('summary',t('Use a response from your existing LLM')),
   el('p',t('Prepare a request containing this conversation, tasks, decisions, questions and recorded relationships. You choose where to send it. Decivora makes no model call; external usage is unknown.'),'notice'));
  const prepare=el('button',t('Prepare LLM request'),'secondary');prepare.dataset.dialogue='prepare';
  const prompt=el('textarea');prompt.id='dialogue_request_'+item.source.id;prompt.readOnly=true;prompt.rows=10;prompt.value=drafts.prompt||'';prompt.setAttribute('aria-label',t('LLM request'));prompt.hidden=!drafts.prompt;
  prepare.onclick=async()=>{prepare.disabled=true;try{const result=await request('/api/command',{action:'prepare_dialogue_review',source_id:item.source.id});drafts.prompt=JSON.stringify(result.request,null,2);prompt.value=drafts.prompt;prompt.hidden=false;prompt.focus();prompt.select();}catch(e){message(e.message,true);}finally{prepare.disabled=false;}};
  const response=el('textarea');response.id='dialogue_response_'+item.source.id;response.rows=8;response.maxLength=16384;response.value=drafts.response||'';response.setAttribute('aria-label',t('Paste structured LLM response'));response.placeholder=t('Paste structured LLM response');response.oninput=()=>drafts.response=response.value;
  const save=el('button',t('Validate and import response'));save.dataset.dialogue='import';
  save.onclick=async()=>{save.disabled=true;try{await request('/api/command',{action:'import_dialogue_response',source_id:item.source.id,response_text:response.value});drafts.response='';message(t('Response imported as proposals. No task status has changed.'));await refresh();}catch(e){save.disabled=false;message(e.message,true);}};
  tools.append(prepare,prompt,el('label',t('Paste structured LLM response')),response,save);box.append(tools);
 }
 for(const proposal of item.relation_proposals||[]){
  const card=el('section',undefined,'card');card.dataset.relationProposal=proposal.id;
  card.append(el('h3',t('Relationship proposal')),el('p',`${proposal.origin_title} → ${proposal.kind} → ${proposal.target_title}`),el('p',`${proposal.origin} · v${proposal.origin_version} → ${proposal.target} · v${proposal.target_version}`,'muted'),el('blockquote',proposal.quote),el('p',proposal.state),el('p',t('Approving adds this relationship only. It does not cancel tasks or retire decisions.'),'notice'));
  if(proposal.stale&&!['Applied','Rejected'].includes(proposal.state))card.append(el('p',t('Relationship context changed. Prepare a fresh request.'),'notice'));
  if(!['Applied','Rejected'].includes(proposal.state)){
   const reason=el('input');reason.id='relation_reason_'+proposal.id;reason.setAttribute('aria-label',t('Review reason'));reason.placeholder=t('Review reason');reason.value=drafts[proposal.id]||'';reason.oninput=()=>drafts[proposal.id]=reason.value;card.append(reason);
   for(const [decision,label] of [['accept','Approve relationship'],['reject','Reject relationship'],['defer','Defer relationship']]){
    const button=el('button',t(label),'secondary');button.dataset.relationDecision=decision;button.disabled=decision==='accept'&&proposal.stale;
    button.onclick=async()=>{button.disabled=true;try{await request('/api/command',{action:'review_dialogue_relation',source_id:item.source.id,proposal_id:proposal.id,decision,key:'rel_'+crypto.randomUUID().replaceAll('-',''),reason:reason.value});await refresh();}catch(e){button.disabled=false;message(e.message,true);}};card.append(button);
   }
  }
  if(proposal.state==='Applied'&&proposal.kind==='required_by'){
   const preview=el('button',t('Review impact if this decision is retired'),'secondary');preview.dataset.relationImpact=proposal.id;preview.onclick=async()=>{preview.disabled=true;try{const decision=state.records.find(r=>r.id===proposal.target);if(!decision)throw Error(t('Relationship context changed. Prepare a fresh request.'));await request('/api/command',{action:'preview_decision_change',decision:decision.id,decision_version:decision.version,base_revision:state.snapshot,key:'rel_impact_'+crypto.randomUUID().replaceAll('-','')});await refresh();setView('questions');}catch(e){preview.disabled=false;message(e.message,true);}};card.append(preview);
  }
  box.append(card);
 }
 for(const proposal of item.answer_proposals||[]){
  const card=el('section',undefined,'card');card.dataset.answerProposal=proposal.id;
  card.append(el('h3',t('Delayed answer proposal')),el('p',proposal.question_text),el('p',`${proposal.question_id} · r${proposal.question_revision} · ${proposal.option_id}: ${proposal.option_label}`,'badge'),el('blockquote',proposal.quote),el('p',proposal.state),el('p',t('Confirming records this answer only. Decision application and task changes require separate approval.'),'notice'));
  if(proposal.stale&&!['Recorded','Rejected'].includes(proposal.state))card.append(el('p',t('Question changed. Prepare a fresh request; this suggestion stays in history.'),'notice'));
  if(!['Recorded','Rejected'].includes(proposal.state)){
   const reason=el('input');reason.id='answer_reason_'+proposal.id;reason.setAttribute('aria-label',t('Review reason'));reason.placeholder=t('Review reason');reason.value=drafts[proposal.id]||'';reason.oninput=()=>drafts[proposal.id]=reason.value;card.append(reason);
   for(const [decision,label] of [['accept','Confirm answer association'],['reject','Reject answer suggestion'],['defer','Defer answer suggestion']]){
    const button=el('button',t(label),'secondary');button.dataset.answerDecision=decision;button.disabled=decision==='accept'&&proposal.stale;
    button.onclick=async()=>{button.disabled=true;try{await request('/api/command',{action:'review_dialogue_answer',source_id:item.source.id,proposal_id:proposal.id,decision,key:'answer_'+crypto.randomUUID().replaceAll('-',''),reason:reason.value});await refresh();}catch(e){button.disabled=false;message(e.message,true);}};card.append(button);
   }
  }
  box.append(card);
 }
 for(const proposal of item.status_changes||[]){
  const card=el('section',undefined,'card');card.dataset.statusProposal=proposal.id;
  const task=state.tasks.find(t=>t.id===proposal.task_id);
  card.append(el('h3',t('Task status proposal')+' · '+(task?.body.title||proposal.task_id)),
   el('p',proposal.from_stage+' → '+proposal.stage,'badge'),el('p',proposal.quote),el('p',proposal.state));
  if(proposal.stage==='Done')card.append(el('p',t('A completion statement is a claim. Current acceptance evidence and a separate scope review are required for Done.'),'notice'));
  if(proposal.stale&& !['Applied','Rejected'].includes(proposal.state))card.append(el('p',t('Task context changed. Prepare a fresh request; the old proposal stays in history.'),'notice'));
  if(!['Applied','Rejected'].includes(proposal.state)){
   const reason=el('input');reason.id='dialogue_reason_'+proposal.id;reason.setAttribute('aria-label',t('Review reason'));reason.placeholder=t('Review reason');reason.value=drafts[proposal.id]||'';reason.oninput=()=>drafts[proposal.id]=reason.value;
   const scope=el('input');scope.type='checkbox';scope.style.width='auto';scope.id='dialogue_scope_'+proposal.id;const label=el('label');label.append(scope,document.createTextNode(t('I reviewed current scope and impact before completion.')));
   card.append(reason);if(proposal.stage==='Done')card.append(label);
   for(const [decision,title] of [['accept','Approve status change'],['reject','Reject status proposal'],['defer','Defer status proposal']]){
    const button=el('button',t(title),'secondary');button.dataset.statusDecision=decision;button.disabled=decision==='accept'&&proposal.stale;
    button.onclick=async()=>{button.disabled=true;try{await request('/api/command',{action:'review_dialogue_status',source_id:item.source.id,proposal_id:proposal.id,decision,key:'dialogue_'+crypto.randomUUID().replaceAll('-',''),reason:reason.value,scope_reviewed:scope.checked});message(t('Status review saved. Completion still follows acceptance and verification rules.'));await refresh();}catch(e){button.disabled=false;message(e.message,true);}};card.append(button);
   }
  }
  box.append(card);
 }
}

function changeLocale(){
 const drafts=[...document.querySelectorAll('input,textarea,select')].filter(n=>n.id).map(n=>({id:n.id,value:n.value,checked:n.checked,start:n.selectionStart,end:n.selectionEnd}));
 const opened=[...document.querySelectorAll('details')].map(n=>n.open);
 const focus=document.activeElement?.id;
 DecivoraI18n.setLocale($('ui-language').value);
 if(state){render();renderMetrics();renderConversations();renderQuestions();renderUnmatchedAnswers();if(selected)show(selected);setView(activeView);}
 for(const draft of drafts){const n=$(draft.id);if(n){n.value=draft.value;n.checked=draft.checked;if(typeof draft.start==='number'&&n.setSelectionRange)n.setSelectionRange(draft.start,draft.end);}}
 [...document.querySelectorAll('details')].forEach((n,i)=>{if(opened[i]!==undefined)n.open=opened[i];});
 if(focus)$(focus)?.focus();
 // A transient message retains its original wording; never re-translate user/server text.
}
$('ui-language').onchange=changeLocale;

function renderBlockers(){
 const root=$('blocker-list');root.replaceChildren();
 const tasks=state.tasks.filter(task=>task.workflow.assessment.blocked&&task.lane!=='Cancelled');$('attention-summary').textContent=t('Finish gates: {count}',{count:state.tasks.filter(task=>task.workflow.assessment.finish_blocked&&task.lane!=='Cancelled').length});
 $('blocker-count').textContent=String(tasks.length);
 if(!tasks.length)root.append(el('p',t('No recorded blockers.'),'muted'));
 for(const task of tasks){const card=el('article',undefined,'card blocked-card');card.append(el('strong','Blocked','blocked-badge'),el('h3',task.body.title),el('p',task.workflow.assessment.blockers.map(b=>b.reason).join(' · ')),el('p',t('Next action: ')+task.workflow.assessment.blockers.map(b=>b.next_action).join(' · ')));appendWaitingLabels(card,task);const button=el('button',t('Review blocker'),'secondary');button.onclick=()=>openTask(task.id,button);card.append(button);root.append(card);}
}
function renderBlockerControls(detail,task){
 const box=el('details');box.append(el('summary',t('Blocker management and history')));
 const reason=el('textarea'),next=el('textarea');reason.id='blocker_reason';next.id='blocker_next_action';reason.maxLength=next.maxLength=1024;
 for(const [name,input] of [[t('Reason / resolution evidence'),reason],[t('Next action'),next]]){const label=el('label',name);label.htmlFor=input.id;box.append(label,input);}
 const gate=el('select');gate.id='blocker_gate';for(const value of ['both','start','finish']){const option=el('option',value);option.value=value;gate.append(option);}const kind=el('select');kind.id='blocker_kind';for(const value of ['manual','decision','approval','input','permission','budget','retry']){const option=el('option',value);option.value=value;kind.append(option);}const owner=el('input');owner.id='blocker_owner';owner.value='unassigned';for(const [name,input] of [[t('Gate'),gate],[t('Waiting reason'),kind],[t('Owner label'),owner]]){const label=el('label',name);label.htmlFor=input.id;box.append(label,input);}
 const button=el('button',task.blocker?.blocked?t('Resolve blocker'):t('Mark as Blocked'));button.disabled=task.lane==='Cancelled';
 button.onclick=async()=>{button.disabled=true;try{await request('/api/command',{action:'task_blocker',task:task.id,task_version:task.version,base_revision:task.blocker.revision,blocked:!task.blocker.blocked,reason:reason.value,next_action:next.value,gate:gate.value,waiting_kind:kind.value,owner:owner.value});message(t('Blocker recorded; workflow status is unchanged.'));await refresh();}catch(e){button.disabled=false;message(e.message,true);}};
 box.append(button);
 for(const row of task.blocker?.history||[])box.append(el('p',`v${row.revision} · ${row.blocked?'Blocked':t('Resolved')} · ${row.reason} · ${row.next_action}`));
 detail.append(box);
}

function renderWorkflowControls(detail,task){
 const rationale=el('select');rationale.id='task_rationale_decision';for(const decision of state.records.filter(r=>r.body.type==='Decision')){const option=el('option',decision.body.title);option.value=decision.id;rationale.append(option);}const rationaleLabel=el('label',t('Task rationale decision'));rationaleLabel.htmlFor=rationale.id;const approveRationale=el('button',t('Approve rationale link'),'secondary');approveRationale.disabled=!rationale.options.length||task.lane==='Cancelled';approveRationale.onclick=async()=>{approveRationale.disabled=true;try{await request('/api/command',{action:'link_task_rationale',task:task.id,target:rationale.value,base_revision:state.snapshot,key:'rationale_'+crypto.randomUUID().replaceAll('-','')});await refresh();}catch(e){approveRationale.disabled=false;message(e.message,true);}};detail.append(rationaleLabel,rationale,approveRationale);

 const target=el('select');target.id='dependency_target';for(const other of state.tasks.filter(o=>o.id!==task.id&&o.lane!=='Cancelled')){const option=el('option',other.body.title);option.value=other.id;target.append(option);}const labelTarget=el('label',t('Completion prerequisite'));labelTarget.htmlFor=target.id;const link=el('button',t('Approve dependency'),'secondary');link.disabled=!target.childNodes.length||task.lane==='Cancelled';link.onclick=async()=>{link.disabled=true;try{await request('/api/command',{action:'link_dependency',task:task.id,target:target.value,base_revision:state.snapshot,key:'dependency_'+crypto.randomUUID().replaceAll('-','')});await refresh();}catch(e){link.disabled=false;message(e.message,true);}};detail.append(labelTarget,target,link);for(const d of task.workflow.assessment.dependencies)detail.append(el('p',`Blocked by · ${d.title||d.id} · ${d.status}`));

 appendWaitingLabels(detail,task);detail.append(el('p',t('Start gate')+': '+(task.workflow.assessment.start_blocked?'Blocked':'Clear')),el('p',t('Completion gate')+': '+(task.workflow.assessment.finish_blocked?'Blocked':'Clear')));
 detail.append(el('p',task.lane+' · '+task.workflow.assessment.readiness),el('p',t('Readiness only covers recorded relationships.'),'muted'));
 for(const b of task.workflow.assessment.blockers)detail.append(el('p',`${b.kind} · ${b.gate} · ${b.reason} · ${b.next_action}`));
 const allowed=state.workflow_transitions[task.lane]||[];
 const reason=el('textarea');reason.id='workflow_reason';reason.maxLength=1024;const label=el('label',t('Reason for stage change'));label.htmlFor=reason.id;detail.append(label,reason);
 const scope=el('input');scope.id='workflow_scope';scope.type='checkbox';scope.style.width='auto';const sl=el('label');sl.append(scope,document.createTextNode(t('I reviewed current scope and impact before completion.')));if(allowed.includes('Done'))detail.append(sl);
 for(const stage of allowed){const button=el('button',stage,'secondary');button.onclick=async()=>{button.disabled=true;try{await request('/api/command',{action:'workflow_transition',task:task.id,task_version:task.version,base_revision:task.workflow.revision,stage,reason:reason.value,key:'stage_'+crypto.randomUUID().replaceAll('-',''),scope_reviewed:scope.checked});await refresh();}catch(e){button.disabled=false;message(e.message,true);}};detail.append(button);}
}
function renderEvidenceControls(detail,task){
 detail.append(el('p',t(state.capabilities.file_checker_configured?'Human review and approved file checks. Automatic tests remain unconfigured.':'Human review only. Automatic tests and file checks require a configured verifier.'),'notice'));
 for(const row of task.workflow.verification.results){const box=el('section',undefined,'criterion-row');box.append(el('strong',`${row.id}: ${row.statement}`),el('p',row.status,'badge'));
 if(row.method==='file_check'){renderFileCheckControls(box,task,row);detail.append(box);continue;}if(row.method!=='human_review'||!['In Review','Awaiting Verification','Done'].includes(task.lane)){box.append(el('p',t('Evidence entry is unavailable for this stage or method.'),'muted'));detail.append(box);continue;}
 const status=el('select');status.id='evidence_status_'+row.id;for(const value of ['pending','passed','failed','not_run','unknown']){const option=el('option',value);option.value=value;status.append(option);}
 const reference=el('input'),note=el('textarea');reference.id='evidence_ref_'+row.id;note.id='evidence_note_'+row.id;reference.maxLength=note.maxLength=1024;
 for(const [name,input] of [[t('Review result'),status],[t('Evidence reference'),reference],[t('What did you verify?'),note]]){const label=el('label',name);label.htmlFor=input.id;box.append(label,input);}
 const save=el('button',t('Save human review'));save.onclick=async()=>{save.disabled=true;try{await request('/api/command',{action:'criterion_evidence',task:task.id,task_version:task.version,contract_version:task.workflow.verification.contract_version,criterion:row.id,status:status.value,reference:reference.value,note:note.value,key:'evidence_'+crypto.randomUUID().replaceAll('-','')});await refresh();}catch(e){save.disabled=false;message(e.message,true);}};box.append(save);detail.append(box);}
}
function renderTaskSources(root,task){const box=el('section');box.dataset.detailSection='sources';box.append(el('h3',t('Sources')));const refs=state.task_sources?.[task.id]||[];for(const id of refs){const source=state.conversation_review.imports.find(i=>i.source.id===id)?.source;if(source)box.append(el('p',source.id,'muted'),el('p',source.text));}if(!refs.length)box.append(el('p',t('No linked conversation source; this may be a manual task.')));root.append(box);}
function renderTaskHistory(root,task){const box=el('section');box.dataset.detailSection='history';box.append(el('h3',t('History')));for(const row of task.lifecycle?.events||[])box.append(el('p',`v${row.version} · ${row.state==='cancelled'?'Cancelled':'To Do'} · ${row.reason} · impact ${row.impact_run}`));for(const row of task.workflow.history)box.append(el('p',`v${row.revision} · ${row.stage} · ${row.reason}`));for(const row of task.workflow.verification.history)box.append(el('p',`${row.criterion} · ${row.status} · ${row.reference} · ${row.note}`));for(const row of task.blocker.history)box.append(el('p',`${row.blocked?'Blocked':'Resolved'} · ${row.reason}`));if(!box.children.length)box.append(el('p',t('No recorded history.')));root.append(box);}
