 const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox',`0 0 780 ${Math.max(130,Math.ceil(records.length/3)*120)}`);svg.style.width='780px';svg.style.maxWidth='none';svg.setAttribute('role','img');svg.setAttribute('aria-label',t('Recorded relationship graph'));const positions=new Map(records.map((r,i)=>[r.id,{x:10+(i%3)*260,y:20+Math.floor(i/3)*120}]));const node=(name,attrs,text)=>{const e=document.createElementNS(ns,name);for(const [k,v] of Object.entries(attrs))e.setAttribute(k,String(v));if(text!==undefined)e.textContent=text;return e;};
 for(const edge of shown){const a=positions.get(edge.origin),b=positions.get(edge.target);const ended=edge.state!=='asserted';svg.append(node('line',{x1:a.x+110,y1:a.y+38,x2:b.x+110,y2:b.y+38,stroke:ended?'#8792a3':'#47759e','stroke-width':2,'stroke-dasharray':ended?'5 4':'none'}));svg.append(node('text',{x:(a.x+b.x)/2+105,y:(a.y+b.y)/2+30,fill:'#384c65','font-size':10},`${ended?'× ':''}${edge.kind} → · v${edge.revision}`));}
 const preview=$('record-preview');preview.replaceChildren();for(const record of records){const pos=positions.get(record.id),task=state.tasks.find(t=>t.id===record.id),status=task?.lane||record.body.type;const group=node('g',{role:'button',tabindex:0,'aria-label':record.body.title,'data-record':record.id});group.style.cursor='pointer';group.append(node('rect',{x:pos.x,y:pos.y,width:230,height:75,rx:7,fill:status==='Cancelled'?'#f1f2f5':task?'#e8f1ff':'#eee9f9',stroke:'#788daa'}),node('text',{x:pos.x+12,y:pos.y+23,'font-size':12,fill:'#243247'},record.body.title.slice(0,34)),node('text',{x:pos.x+12,y:pos.y+44,'font-size':10,fill:'#536782'},`${status} · record v${record.version}`));const open=()=>{graphFocus=record.id;renderGraph();if(task)openTask(task.id,document.querySelector('[data-record="'+record.id+'"]'));else{preview.replaceChildren(el('h3',record.body.title),el('p',record.body.description),el('p',record.body.type+' · '+record.id));}};group.onclick=open;group.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();open();}};svg.append(group);}
