async function loadOperations(){const sequence=++operationsRequest;operationsData=null;$('operations-summary').replaceChildren(el('p',t('Loading diagnostics')));$('operations-runs').replaceChildren();$('operations-errors').replaceChildren();try{const data=await request('/api/operations');if(sequence!==operationsRequest)return;operationsData=data;renderOperations();}catch(error){if(sequence===operationsRequest)$('operations-summary').replaceChildren(el('p',t('Operations unavailable'),'notice'));}}
function renderOperations(){if(!operationsData)return;const data=operationsData,summary=$('operations-summary');summary.replaceChildren();if(!data.available||data.lost_this_process)summary.append(el('p',t('Diagnostics degraded'),'notice'));summary.append(el('p',`${data.environment.toUpperCase()} · ${t('Application processes')}: ${data.application_processes} · ${t('Uptime seconds')}: ${data.uptime_seconds}`),el('p',`${t('Background worker active')}: ${data.background_worker_active} · ${t('Model configured')}: ${data.model_configured} · ${t('Native capture')}: ${data.native_capture}`),el('p',`${t('Capture queue')}: ${Object.entries(data.queue).map(([name,count])=>name+': '+count).join(' · ')||t('No queued capture jobs recorded')} · ${t('Unrecorded writes this process')}: ${data.lost_this_process}`),el('p',`${t('Evicted diagnostic records')}: ${Object.values(data.evicted).reduce((sum,count)=>sum+count,0)} · ${t('Retained traces')}: ${data.limits?.retained_runs??t('Unknown')} · ${t('Retained error groups')}: ${data.limits?.retained_error_groups??t('Unknown')}`));
 const runs=$('operations-runs');runs.replaceChildren();const outcome=$('operations-filter').value,search=$('operations-search').value.toLowerCase();for(const run of data.runs.filter(r=>(outcome==='all'||r.outcome===outcome)&&r.id.toLowerCase().includes(search))){const item=el('details',undefined,'card operation-run');item.dataset.operationId=run.id;item.dataset.outcome=run.outcome;item.append(el('summary',`${run.action} · ${run.outcome} · ${run.duration_ms??t('Unknown')} ms`),el('p',run.id,'muted'),el('p',new Date(run.started*1000).toLocaleString()));item.append(el('p',run.identity?`${t('Actor')}: ${run.identity.actor_id} · ${run.identity.actor_type} · ${t('Workspace')}: ${run.identity.workspace} · ${t('Observed authorization revision')}: ${run.identity.authz_revision}`:t('Actor identity was not recorded for this trace.')));for(const span of run.stages)item.append(el('p',`${span.position}. ${span.component} / ${span.stage} · ${span.outcome} · ${span.duration_ms??t('Unknown')} ms${span.code?' · '+span.code:''}`));runs.append(item);}if(!runs.childNodes.length)runs.append(el('p',t('No matching command traces.')));
 const errors=$('operations-errors');errors.replaceChildren();for(const error of data.errors){const item=el('article',undefined,'card');item.append(el('strong',error.code),el('p',`${error.endpoint} · ${t('Occurrences')}: ${error.count}`),el('p',new Date(error.last_seen*1000).toLocaleString()));errors.append(item);}if(!data.errors.length)errors.append(el('p',t('No recorded HTTP errors.')));
}
$('operations-refresh').onclick=loadOperations;$('operations-filter').onchange=renderOperations;$('operations-search').oninput=renderOperations;
